import{c as a,Z as i,Q as e,j as l,m as r,o as u}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"静女","description":"","frontmatter":{"title":"静女","author":"佚名","dynasty":"先秦"},"headers":[],"relativePath":"books/shici/shijing/7.md","filePath":"books/shici/shijing/7.md"}'),s={name:"books/shici/shijing/7.md"};function n(h,o,q,p,c,d){const t=i("PoemNav");return e(),l("div",null,[o[0]||(o[0]=r('<h1 id="静女" tabindex="-1">静女 <a class="header-anchor" href="#静女" aria-label="Permalink to &quot;静女&quot;">​</a></h1><p><strong>[先秦] 佚名</strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>静女其姝，俟我于城隅。爱而不见，搔首踟蹰。</p><p>静女其娈，贻我彤管。彤管有炜，说怿女美。</p><p>自牧归荑，洵美且异。匪女之为美，美人之贻。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>静女：娴静的女子</li><li>姝：美丽</li><li>俟：等待</li><li>城隅：城墙的角落</li><li>爱：通&quot;薆&quot;，隐藏</li><li>搔首：挠头</li><li>踟蹰：徘徊不定</li><li>娈：美好</li><li>贻：赠送</li><li>彤管：红色的管状植物，一说为红管笔</li><li>炜：鲜明有光</li><li>说怿：喜爱</li><li>女：通&quot;汝&quot;，你</li><li>牧：郊外</li><li>归：通&quot;馈&quot;，赠送</li><li>荑：初生的茅草</li><li>洵：确实</li><li>匪：通&quot;非&quot;</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>娴静的姑娘多么美丽，在城墙角落等我。她躲藏起来让我找不到，我挠着头徘徊不定。</p><p>娴静的姑娘多么美好，送给我红色的管草。红色的管草光彩鲜明，我喜欢你的美丽。</p><p>从郊外采来茅草送给我，确实美丽又奇异。不是茅草本身美丽，因为是美人赠送的。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首诗是《诗经》中的爱情诗名篇，描写了一对青年男女约会的情景，表现了纯真美好的爱情。</p><p>第一章写约会时的情景。&quot;静女其姝，俟我于城隅&quot;，点明了人物、地点和事件。&quot;爱而不见，搔首踟蹰&quot;，写女子故意躲藏，男子焦急等待的情景，生动地表现了恋爱中的甜蜜和焦急。</p><p>第二章写女子赠送信物。&quot;静女其娈，贻我彤管&quot;，写女子送给男子红色的管草作为信物。&quot;彤管有炜，说怿女美&quot;，男子赞美信物的美丽，实际上是赞美赠送信物的女子。</p><p>第三章写男子对信物的珍视。&quot;自牧归荑，洵美且异&quot;，写女子又赠送了郊外的茅草。&quot;匪女之为美，美人之贻&quot;，是全诗的点睛之笔。男子说不是茅草本身美丽，而是因为它是美人赠送的。这种&quot;爱屋及乌&quot;的心理，将恋爱中的深情表现得淋漓尽致。</p><p>全诗语言清新，情感真挚，将恋爱中的甜蜜、焦急和深情表现得细腻动人，是《诗经》爱情诗的典范之作。</p><hr><h2 id="关于《诗经》" tabindex="-1">关于《诗经》 <a class="header-anchor" href="#关于《诗经》" aria-label="Permalink to &quot;关于《诗经》&quot;">​</a></h2><blockquote><p>《诗经》是中国最早的诗歌总集，收录了西周初年至春秋中叶（前11世纪至前6世纪）的诗歌305篇，分为&quot;风&quot;&quot;雅&quot;&quot;颂&quot;三部分。《诗经》内容丰富，反映了周代社会生活的方方面面，是中国现实主义文学的源头。</p><p><a href="/books/shici/shijing/1.html">查看《诗经》更多作品 →</a></p></blockquote>',21)),u(t)])}const b=a(s,[["render",n]]);export{m as __pageData,b as default};
